#!/bin/bash
IFS='.' read -r IP1 IP2 IP3 IP4 <<< "$1"; MASK=$((0xffffffff << (32 - "$2") & 0xffffffff)); MASK1=$(( (MASK >> 24) & 255 )); MASK2=$(( (MASK >> 16) & 255 )); MASK3=$(( (MASK >> 8) & 255 )); MASK4=$(( MASK & 255 )); NET1=$((IP1 & MASK1)); NET2=$((IP2 & MASK2)); NET3=$((IP3 & MASK3)); NET4=$((IP4 & MASK4)); BROADCAST1=$((NET1 | ((~MASK1) & 255) )); BROADCAST2=$((NET2 | ((~MASK2) & 255) )); BROADCAST3=$((NET3 | ((~MASK3) & 255) )); BROADCAST4=$((NET4 | ((~MASK4) & 255) )); FIRST="$NET1.$NET2.$NET3.$((NET4 + 1))"; LAST="$BROADCAST1.$BROADCAST2.$BROADCAST3.$((BROADCAST4 - 1))"; printf "%s - %s" "$FIRST" "$LAST" 
